-- ==============================================================================
-- ⚠️ LA GROTTE (MONASTIR) — 60-DAY REALISTIC TEST DATA SEED SCRIPT
-- WARNING: TEST DATA ONLY! DO NOT RUN AGAINST REAL RESTAURANT OPERATIONAL RECORDS!
-- Purpose: Populates 18 ingredients across all 5 categories (with 3 low-stock items),
--          4 suppliers, 6 menu items + BOM, ~60 days of deliveries & stock counts,
--          ~60 days of realistic sales, and detailed waste logs.
-- Run in: Supabase SQL Editor (https://supabase.com/dashboard/project/atcpmlaijqxvehuwacpc/sql/new)
-- ==============================================================================

BEGIN;

-- Ensure waste_logs table exists if migration has not been applied yet
CREATE TABLE IF NOT EXISTS public.waste_logs (
    id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),
    ingredient_id UUID NOT NULL REFERENCES public.ingredients(id) ON DELETE CASCADE,
    quantity NUMERIC(10, 3) NOT NULL CHECK (quantity >= 0),
    unit_cost_at_time NUMERIC(10, 3) NOT NULL,
    reason TEXT NOT NULL CHECK (reason IN ('spoilage', 'spillage', 'breakage', 'staff_meal', 'comp', 'other')),
    logged_by TEXT NOT NULL,
    date DATE NOT NULL DEFAULT CURRENT_DATE,
    shift TEXT NOT NULL CHECK (shift IN ('morning', 'evening')),
    notes TEXT,
    created_at TIMESTAMPTZ NOT NULL DEFAULT timezone('utc'::text, now())
);

-- 1. CLEANUP PREVIOUS TEST SEED ROWS (Safe Idempotency via deterministic IDs)
DELETE FROM public.waste_logs WHERE notes LIKE '%Inventaire%' OR notes LIKE '%Oxydation%' OR notes LIKE '%Humidité%' OR notes LIKE '%Bouteille%' OR notes LIKE '%Repas%';
DELETE FROM public.sales WHERE source = 'Caisse Monastir';
DELETE FROM public.recipe_ingredients WHERE menu_item_id IN ('33333333-4444-4000-8000-000000000001', '33333333-4444-4000-8000-000000000002', '33333333-4444-4000-8000-000000000003', '33333333-4444-4000-8000-000000000004', '33333333-4444-4000-8000-000000000005', '33333333-4444-4000-8000-000000000006');
DELETE FROM public.menu_items WHERE id IN ('33333333-4444-4000-8000-000000000001', '33333333-4444-4000-8000-000000000002', '33333333-4444-4000-8000-000000000003', '33333333-4444-4000-8000-000000000004', '33333333-4444-4000-8000-000000000005', '33333333-4444-4000-8000-000000000006');
DELETE FROM public.deliveries WHERE notes LIKE '%BL-%-LG%';
DELETE FROM public.stock_counts WHERE notes LIKE '%Inventaire régulier%';
DELETE FROM public.ingredients WHERE id IN ('22222222-3333-4000-8000-000000000001', '22222222-3333-4000-8000-000000000002', '22222222-3333-4000-8000-000000000003', '22222222-3333-4000-8000-000000000004', '22222222-3333-4000-8000-000000000005', '22222222-3333-4000-8000-000000000006', '22222222-3333-4000-8000-000000000007', '22222222-3333-4000-8000-000000000008', '22222222-3333-4000-8000-000000000009', '22222222-3333-4000-8000-000000000010', '22222222-3333-4000-8000-000000000011', '22222222-3333-4000-8000-000000000012', '22222222-3333-4000-8000-000000000013', '22222222-3333-4000-8000-000000000014', '22222222-3333-4000-8000-000000000015', '22222222-3333-4000-8000-000000000016', '22222222-3333-4000-8000-000000000017', '22222222-3333-4000-8000-000000000018');
DELETE FROM public.suppliers WHERE id IN ('11111111-2222-4000-8000-000000000001', '11111111-2222-4000-8000-000000000002', '11111111-2222-4000-8000-000000000003', '11111111-2222-4000-8000-000000000004');

-- 2. SUPPLIERS
ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, contact = EXCLUDED.contact, notes = EXCLUDED.notes;

-- 3. INGREDIENTS (18 items across all 5 categories, 3 low stock)
ON CONFLICT (id) DO UPDATE SET 
  name = EXCLUDED.name, unit = EXCLUDED.unit, category = EXCLUDED.category,
  cost_per_unit = EXCLUDED.cost_per_unit, current_stock = EXCLUDED.current_stock,
  min_alert_threshold = EXCLUDED.min_alert_threshold, location = EXCLUDED.location;

-- 4. MENU ITEMS
ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, pos_reference = EXCLUDED.pos_reference, category = EXCLUDED.category, selling_price = EXCLUDED.selling_price;

-- 5. RECIPE INGREDIENTS (BOM)
ON CONFLICT (menu_item_id, ingredient_id) DO UPDATE SET quantity_per_unit = EXCLUDED.quantity_per_unit;

-- 6. DELIVERIES (~60 DAYS)

-- 7. STOCK COUNTS (~60 DAYS)

-- 8. SALES (~60 DAYS)

-- 9. WASTE LOGS

COMMIT;

-- VERIFICATION SUMMARY
SELECT 
  (SELECT count(*) FROM public.suppliers WHERE id IN ('11111111-2222-4000-8000-000000000001', '11111111-2222-4000-8000-000000000002', '11111111-2222-4000-8000-000000000003', '11111111-2222-4000-8000-000000000004')) as suppliers_count,
  (SELECT count(*) FROM public.ingredients WHERE id IN ('22222222-3333-4000-8000-000000000001', '22222222-3333-4000-8000-000000000002', '22222222-3333-4000-8000-000000000003', '22222222-3333-4000-8000-000000000004', '22222222-3333-4000-8000-000000000005', '22222222-3333-4000-8000-000000000006', '22222222-3333-4000-8000-000000000007', '22222222-3333-4000-8000-000000000008', '22222222-3333-4000-8000-000000000009', '22222222-3333-4000-8000-000000000010', '22222222-3333-4000-8000-000000000011', '22222222-3333-4000-8000-000000000012', '22222222-3333-4000-8000-000000000013', '22222222-3333-4000-8000-000000000014', '22222222-3333-4000-8000-000000000015', '22222222-3333-4000-8000-000000000016', '22222222-3333-4000-8000-000000000017', '22222222-3333-4000-8000-000000000018')) as ingredients_count,
  (SELECT count(*) FROM public.menu_items WHERE id IN ('33333333-4444-4000-8000-000000000001', '33333333-4444-4000-8000-000000000002', '33333333-4444-4000-8000-000000000003', '33333333-4444-4000-8000-000000000004', '33333333-4444-4000-8000-000000000005', '33333333-4444-4000-8000-000000000006')) as menu_items_count,
  (SELECT count(*) FROM public.recipe_ingredients WHERE menu_item_id IN ('33333333-4444-4000-8000-000000000001', '33333333-4444-4000-8000-000000000002', '33333333-4444-4000-8000-000000000003', '33333333-4444-4000-8000-000000000004', '33333333-4444-4000-8000-000000000005', '33333333-4444-4000-8000-000000000006')) as recipe_links_count,
  (SELECT count(*) FROM public.deliveries WHERE notes LIKE '%BL-%-LG%') as deliveries_count,
  (SELECT count(*) FROM public.stock_counts WHERE notes LIKE '%Inventaire régulier%') as stock_counts_count,
  (SELECT count(*) FROM public.sales WHERE source = 'Caisse Monastir') as sales_records_count,
  (SELECT count(*) FROM public.waste_logs WHERE logged_by = 'Chef Marc') as waste_logs_count,
  (SELECT count(*) FROM public.ingredients WHERE current_stock < min_alert_threshold) as low_stock_alerts_count;
